window.SHOWS = [{"id": 169, "name": "Breaking Bad", "premiered": "2008-01-20", "ended": "2019-10-11", "rating": 9.2, "genres": ["Drama", "Crime", "Thriller"], "summary": "<p><b>Breaking Bad</b> follows protagonist Walter White, a chemistry teacher who lives in New Mexico with his wife and teenage son who has cerebral palsy. White is diagnosed with Stage III cancer and given a prognosis of two years left to live. With a new sense of fearlessness based on his medical prognosis, and a desire to secure his family's financial security, White chooses to enter a dangerous world of drugs and crime and ascends to power in this world. The series explores how a fatal diagnosis such as White's releases a typical man from the daily concerns and constraints of normal society and follows his transformation from mild family man to a kingpin of the drug trade.</p>", "poster": "https://static.tvmaze.com/uploads/images/original_untouched/501/1253519.jpg", "backdrop": "https://static.tvmaze.com/uploads/images/original_untouched/219/547904.jpg", "episodes": [{"id": 12192, "season": 1, "number": 1, "name": "Pilot", "rating": 8.3, "airdate": "2008-01-20", "runtime": 60, "summary": "<p>A high-school chemistry teacher (Bryan Cranston) is diagnosed with a deadly cancer, so he puts his expertise to use and teams with an ex-student (Aaron Paul) to manufacture top-grade crystal meth in hopes of providing for his family after he's gone.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012681.jpg"}, {"id": 12193, "season": 1, "number": 2, "name": "Cat's in the Bag...", "rating": 7.9, "airdate": "2008-01-27", "runtime": 60, "summary": "<p>After the accident in the desert, Walter and Jesse need to dispose of the unfortunate mess in their rolling lab of an RV, and Skyler begins to suspect that Walter and Jesse are involved in some mysterious goings-on.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012682.jpg"}, {"id": 12194, "season": 1, "number": 3, "name": "...and the Bag's in the River", "rating": 8.1, "airdate": "2008-02-10", "runtime": 60, "summary": "<p>Walter and Jesse fight about the latter's drug use, so he leaves, forcing Walter to deal with their captive, Krazy-8 (Max Arciniega); Hank uses scared-straight tactics with Walter Jr. when his aunt suspects he's smoking pot; Skyler is furious when Walter stays away from home.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012683.jpg"}, {"id": 12195, "season": 1, "number": 4, "name": "Cancer Man", "rating": 7.6, "airdate": "2008-02-17", "runtime": 60, "summary": "<p>Walter announces to the family that he has cancer; the DEA believes there is a new big-time player in the Albuquerque drug business; a depressed Walter takes his anger out on a worthy recipient; Jesse pays a surprise visit to his parents' house.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012684.jpg"}, {"id": 12196, "season": 1, "number": 5, "name": "Gray Matter", "rating": 7.8, "airdate": "2008-02-24", "runtime": 60, "summary": "<p>At a birthday party for a successful former science colleague, Walter is offered a job; Jesse tries gaining legitimate employment but winds up back cooking meth, and an inferior kind at that; Skyler assembles the family for an intervention to get Walter to agree to chemotherapy, but he's concerned about quality-of-life issues and their financial difficulties.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012685.jpg"}, {"id": 12197, "season": 1, "number": 6, "name": "Crazy Handful of Nothin'", "rating": 8.8, "airdate": "2008-03-02", "runtime": 60, "summary": "<p>Walter, in the throes of his chemotherapy treatment and needing money more than ever, agrees to cook more crystal meth with Jesse; Skinny Pete hooks Jesse up with an important new contact, while the DEA intensifies its investigation of Albuquerque's new drug kingpin.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012686.jpg"}, {"id": 12198, "season": 1, "number": 7, "name": "A No-Rough-Stuff-Type Deal", "rating": 8, "airdate": "2008-03-09", "runtime": 60, "summary": "<p>Walter and Jesse do business with a new partner-in-crime, but immediately run into \"production problems,\" which necessitates a nearly impossible mission to knock off a chemical-supply house. Meanwhile, Marie throws a baby shower for Skyler and presents her with an unusual gift that shows a different side of the aunt-to-be.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012687.jpg"}, {"id": 12199, "season": 2, "number": 1, "name": "Seven Thirty-Seven", "rating": 7.9, "airdate": "2009-03-08", "runtime": 60, "summary": "<p>Season 2 kicks off with Walt and Jesse once again bearing witness to Tuco's incendiary disposition, which leads them to the conclusion that it's time to put an end to their business dealings with him. But the question is how. Meanwhile, Hank serves as a go-between for estranged sisters Skyler and Marie.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012709.jpg"}, {"id": 12200, "season": 2, "number": 2, "name": "Grilled", "rating": 8.4, "airdate": "2009-03-15", "runtime": 60, "summary": "<p><br></p><p>Trying to dissociate themselves from the volatile Tuco takes a bad turn when Walt and Jesse get trapped with the dealer, and Skyler, worried about her missing husband, receives comfort from her sister and brother-in-law. Hank, meanwhile, pays a business call on Jesse's mother.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012710.jpg"}, {"id": 12201, "season": 2, "number": 3, "name": "Bit by a Dead Bee", "rating": 7.9, "airdate": "2009-03-22", "runtime": 60, "summary": "<p>Walt and Jesse attempt to cover their tracks and distance themselves from Tuco, but they soon find that business is taking a hit along with their financial situation. Meanwhile, Hank and his DEA investigation into the meth ring get a major break that just might put Walt and Jesse in their crosshairs.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012711.jpg"}, {"id": 12202, "season": 2, "number": 4, "name": "Down", "rating": 7.5, "airdate": "2009-03-29", "runtime": 60, "summary": "<p>Despite Walt's attempt to reconnect with the family, a suspicious Skyler keeps him at arm's length and worries about what he's been up to while he's been away from the house; Jesse finds himself on the streets once again and struggles to improve his lot in life.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012712.jpg"}, {"id": 12203, "season": 2, "number": 5, "name": "Breakage", "rating": 7.9, "airdate": "2009-04-05", "runtime": 60, "summary": "<p>Hank deals with some lingering aftereffects from his confrontation with Tuco; bills are piling up at the White house and tensions are beginning to run high; Jesse organizes a crew of dealers to take their product to the streets.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012713.jpg"}, {"id": 12204, "season": 2, "number": 6, "name": "Peekaboo", "rating": 8.3, "airdate": "2009-04-12", "runtime": 60, "summary": "<p>Walt returns to teaching at the high school; when Skinny Pete gets taken advantage of and ripped off, Jesse steps in, but bites off more than he can chew; Skyler takes the opportunity to show her appreciation for Gretchen's kindness in picking up the tab for Walt's treatments.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012714.jpg"}, {"id": 12205, "season": 2, "number": 7, "name": "Negro Y Azul", "rating": 8.1, "airdate": "2009-04-19", "runtime": 60, "summary": "<p>Walt and Jesse contemplate an expansion of their business; Hank experiences a hassle in El Paso as he tries to adapt to his new coworkers; Skyler's new job opportunity leads to her reconnecting with an ex-colleague; and Jesse interacts with his new landlady.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012715.jpg"}, {"id": 12206, "season": 2, "number": 8, "name": "Better Call Saul", "rating": 8.7, "airdate": "2009-04-26", "runtime": 60, "summary": "<p>Badger's brush with the law leads Walt and Jesse to call in a shady lawyer; the DEA believes it has a line on the mysterious and elusive \"Heisenberg\"; Hank's stint in El Paso is up and he returns to Albuquerque, but his mental makeup causes concern for Marie.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012716.jpg"}, {"id": 12207, "season": 2, "number": 9, "name": "4 Days Out", "rating": 8.4, "airdate": "2009-05-03", "runtime": 60, "summary": "<p>After undergoing a PET-CAT scan and fearing the worst, Walt takes lawyer Saul's advice and hunkers down for a marathon session of cooking product; Jesse's romance with his landlady is heating up, but must cool off quickly when he and Walt head for the desert to take care of business.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012717.jpg"}, {"id": 12208, "season": 2, "number": 10, "name": "Over", "rating": 8, "airdate": "2009-05-10", "runtime": 60, "summary": "<p>The Whites throw a party to thank family and friends for their support through Walt's trying time, but it turns ugly when he and Hank get into a bitter argument; later, a pent-up and fed-up Walt tries to occupy his time with home-improvement projects. Worried about Walt's physical and emotional states, Skyler confides in her boss; Jane keeps her relationship with Jesse a secret from her father.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012718.jpg"}, {"id": 12209, "season": 2, "number": 11, "name": "Mandala", "rating": 8, "airdate": "2009-05-17", "runtime": 60, "summary": "<p>Saul suggests a new business partner for Walt and Jesse after they begin to lose their dealers to some unforeseen circumstances. At work, Skyler confronts Ted after she uncovers some unnerving information; and Jesse opens up to Jane about what he does for a living, with disastrous results.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012719.jpg"}, {"id": 12210, "season": 2, "number": 12, "name": "Phoenix", "rating": 8.8, "airdate": "2009-05-24", "runtime": 60, "summary": "<p>A new addition joins the White family as Walter Jr. attempts to help out his struggling family by launching a new Web site. Elsewhere, Jesse's addiction worsens and his relationship with Jane begins to negatively impact Walt and her father.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012720.jpg"}, {"id": 12211, "season": 2, "number": 13, "name": "ABQ", "rating": 8.3, "airdate": "2009-05-31", "runtime": 60, "summary": "<p>In the Season 2 finale, Skyler's frustration with Walt's secrecy boils over; Jesse is dealt a devastating blow that leads him down a path of self-destruction, and only Walt is willing to help him; and a grief-stricken Donald experiences more tragedy.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012721.jpg"}, {"id": 12212, "season": 3, "number": 1, "name": "No M\u00e1s", "rating": 7.8, "airdate": "2010-03-21", "runtime": 60, "summary": "<p>In the third-season premiere, Walt faces a new threat on a new front and deals with an increasingly angry Skyler, who must consider what to do next with her life and the kids'. Meanwhile, Jesse comes face-to-face with some startling self-revelations.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012733.jpg"}, {"id": 12213, "season": 3, "number": 2, "name": "Caballo sin Nombre", "rating": 8, "airdate": "2010-03-28", "runtime": 60, "summary": "<p>Despite ever-increasing tension between Walt and Skyler, he pulls out all the stops in an effort to reconcile with the family. Elsewhere, Saul is instrumental in getting Jesse involved in a most-unusual investment opportunity.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012734.jpg"}, {"id": 12214, "season": 3, "number": 3, "name": "I.F.T.", "rating": 7.9, "airdate": "2010-04-04", "runtime": 60, "summary": "<p>Walt disregards Skyler's demands and the rift between them widens dramatically, pushing her to take even more drastic steps. Meanwhile, continuing anxiety and panic attacks plague Hank, which leads to a serious situation at the Drug Enforcement Agency.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012735.jpg"}, {"id": 12215, "season": 3, "number": 4, "name": "Green Light", "rating": 7.9, "airdate": "2010-04-11", "runtime": 60, "summary": "<p>Skyler's latest bit of bad news proves to be a blow to Walt, and his loss of control endangers his job and his business relationships with Saul and Jesse. Hank goes full-speed ahead into the agency's investigation of the blue-meth case, while Jesse cooks up a new plan.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012736.jpg"}, {"id": 12216, "season": 3, "number": 5, "name": "M\u00e1s", "rating": 8.1, "airdate": "2010-04-18", "runtime": 60, "summary": "<p>When Gus intensifies efforts to persuade Walt to get back in the meth business, Jesse takes exception and a rift appears in his and Walt's personal relationship. Meanwhile, Skyler's new relationship isn't turning out as she'd like; and Marie tells Skyler about her concerns for the increasingly troubled Hank and his well-being.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012737.jpg"}, {"id": 12217, "season": 3, "number": 6, "name": "Sunset", "rating": 8.8, "airdate": "2010-04-25", "runtime": 60, "summary": "<p>Walt moves into new digs and a distraught Walter Jr. demands to know just where his parents' relationship stands. Meanwhile, Hank's investigation is beginning to hit too close to home for Walt, causing serious concerns for him and Jesse.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012738.jpg"}, {"id": 12218, "season": 3, "number": 7, "name": "One Minute", "rating": 9.2, "airdate": "2010-05-02", "runtime": 60, "summary": "<p>Hank's behavior becomes increasingly more unpredictable and volatile, which leads to a confrontation with Jesse and problems at the DEA; Skyler wants Walt to make a deal; and Gus' decisions result in some serious consequences.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012739.jpg"}, {"id": 12219, "season": 3, "number": 8, "name": "I See You", "rating": 7.9, "airdate": "2010-05-09", "runtime": 60, "summary": "<p>The White and Schrader families anxiously await word on Hank's condition. Meanwhile, Jesse takes care of business at the lab while Walt tries to make peace with Gus, but after witnessing a terrifying flash of anger, Walt starts to fear for his and his family's lives.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012740.jpg"}, {"id": 12220, "season": 3, "number": 9, "name": "Kafkaesque", "rating": 7.9, "airdate": "2010-05-16", "runtime": 60, "summary": "<p>Hank's stay in the hospital is accompanied by some daunting bills, but Skyler thinks she has a way of dealing with them. Meanwhile, some of the problems between Walt and Gus are ameliorated; and Jesse seeks more independence and grabs a profitable opportunity that presents itself.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012741.jpg"}, {"id": 12221, "season": 3, "number": 10, "name": "Fly", "rating": 7.3, "airdate": "2010-05-23", "runtime": 60, "summary": "<p>When Walt becomes driven to distraction by a contaminant in the lab, he refuses to cook meth until they are able to get rid of it.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012742.jpg"}, {"id": 12222, "season": 3, "number": 11, "name": "Abiquiu", "rating": 7.9, "airdate": "2010-05-30", "runtime": 60, "summary": "<p>Skyler's increased involvement in Walt's business causes him concern; Hank's recovery is plagued by setbacks; and Jesse makes a surprising discovery as he gets more involved in his new enterprise.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012743.jpg"}, {"id": 12223, "season": 3, "number": 12, "name": "Half Measures", "rating": 9.2, "airdate": "2010-06-06", "runtime": 60, "summary": "<p>Jesse ignores Walt's advice and finds himself in a dangerous situation. Fearing for Jesse's safety, Walt takes drastic measures to try to put things right. And tragedy strikes following an unexpected confrontation.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012744.jpg"}, {"id": 12224, "season": 3, "number": 13, "name": "Full Measure", "rating": 9.1, "airdate": "2010-06-13", "runtime": 60, "summary": "<p>Jesse goes on the lam in the third-season finale. But Mike is right on his heels, so Walt works a deal with Gus and comes up with an unsettling plan that might help guarantee both his and Jesse's safety.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012745.jpg"}, {"id": 12225, "season": 4, "number": 1, "name": "Box Cutter", "rating": 8.2, "airdate": "2011-07-17", "runtime": 60, "summary": "<p>In the Season 4 opener, Walt and Jesse are confronted by the life-threatening consequences of their actions. Meanwhile, Skyler contends with a puzzling disappearance, and Marie finds it difficult to help a recovering Hank.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012751.jpg"}, {"id": 12226, "season": 4, "number": 2, "name": "Thirty-Eight Snub", "rating": 7.8, "airdate": "2011-07-24", "runtime": 60, "summary": "<p>Walt tries to establish a new alliance as he plots his next move. Meanwhile, Skyler urges Walt to consider a business opportunity that could keep the family safe.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012752.jpg"}, {"id": 12227, "season": 4, "number": 3, "name": "Open House", "rating": 7.3, "airdate": "2011-07-31", "runtime": 60, "summary": "<p>Goings-on at Jesse's place start to get out of control; Skyler reluctantly turns to Saul for help; Marie settles back into an old habit; and Hank hears from an old friend who needs assistance.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012753.jpg"}, {"id": 12228, "season": 4, "number": 4, "name": "Bullet Points", "rating": 7.8, "airdate": "2011-08-07", "runtime": 60, "summary": "<p>The Cartel makes a power move; Skyler and Walt reveal something embarrassing to the family; and Jesse's misdeeds bring some unwanted attention.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012754.jpg"}, {"id": 12229, "season": 4, "number": 5, "name": "Shotgun", "rating": 7.7, "airdate": "2011-08-14", "runtime": 60, "summary": "<p>Jesse's disappearance leaves Walt fearing the worst; Skyler has a surprising reunion; and Hank gives Det. Roberts bad news.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012755.jpg"}, {"id": 12230, "season": 4, "number": 6, "name": "Cornered", "rating": 7.8, "airdate": "2011-08-21", "runtime": 60, "summary": "<p>A shocking discovery unsettles Skyler; Walter Jr. leans on his father to make a special purchase; Mike gets surprise help from Jesse.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012756.jpg"}, {"id": 12231, "season": 4, "number": 7, "name": "Problem Dog", "rating": 8.2, "airdate": "2011-08-28", "runtime": 60, "summary": "<p>A frustrated Walt takes on a risky gamble; Skyler encounters problems with her latest business venture; Hank requires Walter Jr.'s services for an unusual reason.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012757.jpg"}, {"id": 12232, "season": 4, "number": 8, "name": "Hermanos", "rating": 8.3, "airdate": "2011-09-04", "runtime": 60, "summary": "<p>Skyler devises a plan to cure her money woes; Hank recruits Walt to help him work out a theory, while Walt grows impatient with Jesse.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012758.jpg"}, {"id": 12233, "season": 4, "number": 9, "name": "Bug", "rating": 8.2, "airdate": "2011-09-11", "runtime": 60, "summary": "<p>Mistakes from Skyler's past prove to be impactful to the present; Gus is spurred to action against rivals; Jesse seeks help from Walt but the results are mixed.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012759.jpg"}, {"id": 12234, "season": 4, "number": 10, "name": "Salud", "rating": 9.1, "airdate": "2011-09-18", "runtime": 60, "summary": "<p>The family becomes gravely concerned when Walt doesn't show up for his son's 16th birthday celebration. And Jesse's lab skills are tested in Walt's absence.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012760.jpg"}, {"id": 12235, "season": 4, "number": 11, "name": "Crawl Space", "rating": 9, "airdate": "2011-09-25", "runtime": 60, "summary": "<p>Walt moves to protect his secret and Gus; Skyler is stymied in her attempt to help Ted with his financial problem.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012761.jpg"}, {"id": 12236, "season": 4, "number": 12, "name": "End Times", "rating": 9, "airdate": "2011-10-02", "runtime": 60, "summary": "<p>Hank leans on Gomez to explore one final lead, as Walt scrambles to protect his family. Meanwhile, Jesse learns some unsettling news and races to share it with Walt.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012762.jpg"}, {"id": 12237, "season": 4, "number": 13, "name": "Face Off", "rating": 9.1, "airdate": "2011-10-09", "runtime": 60, "summary": "<p>The fourth season ends with Walt and Jesse squaring off against Gus. Elsewhere, Walt acquires a surprise confederate with help from Saul.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012763.jpg"}, {"id": 12238, "season": 5, "number": 1, "name": "Live Free or Die", "rating": 7.7, "airdate": "2012-07-15", "runtime": 60, "summary": "<p>In the series 5 premiere, Walt deals with the aftermath of the explosion, while Hank wraps up his investigation of Gus and his criminal empire.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012774.jpg"}, {"id": 12239, "season": 5, "number": 2, "name": "Madrigal", "rating": 7.8, "airdate": "2012-07-22", "runtime": 60, "summary": "<p>Walt and Jesse seek out an unlikely partner for a new business venture. The DEA follows up new leads in its investigation.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012775.jpg"}, {"id": 12240, "season": 5, "number": 3, "name": "Hazard Pay", "rating": 7.6, "airdate": "2012-07-29", "runtime": 60, "summary": "<p>Walt and Jesse put a business plan into action. Walt confesses a secret to Marie.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012776.jpg"}, {"id": 12241, "season": 5, "number": 4, "name": "Fifty-One", "rating": 7.4, "airdate": "2012-08-05", "runtime": 60, "summary": "<p>Walt celebrates another birthday. Skyler considers her options. An associate complicates Walt and Jesse's plan.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012777.jpg"}, {"id": 12242, "season": 5, "number": 5, "name": "Dead Freight", "rating": 8.3, "airdate": "2012-08-12", "runtime": 60, "summary": "<p>Walt's team must get creative to obtain the materials they need to continue their operation.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012778.jpg"}, {"id": 12243, "season": 5, "number": 6, "name": "Buyout", "rating": 7.8, "airdate": "2012-08-19", "runtime": 60, "summary": "<p>Walt, Jesse, and Mike struggle over the future of their business, as occupational hazards weigh on Jesse.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012779.jpg"}, {"id": 12244, "season": 5, "number": 7, "name": "Say My Name", "rating": 8.3, "airdate": "2012-08-26", "runtime": 60, "summary": "<p>Walt takes control of business matters as Mike grapples with the consequences of his actions.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012780.jpg"}, {"id": 12245, "season": 5, "number": 8, "name": "Gliding Over All", "rating": 8.9, "airdate": "2012-09-02", "runtime": 60, "summary": "<p>Walt ties up loose ends. Seeing the evidence of his success, he makes a startling and dangerous decision.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012781.jpg"}, {"id": 12246, "season": 5, "number": 9, "name": "Blood Money", "rating": 8.3, "airdate": "2013-08-11", "runtime": 60, "summary": "<p>As Walt and Jesse adjust to life out of the business, Hank grapples with a troubling lead.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012782.jpg"}, {"id": 12247, "season": 5, "number": 10, "name": "Buried", "rating": 7.9, "airdate": "2013-08-18", "runtime": 60, "summary": "<p>While Skyler's past catches up with her, Walt covers his tracks. Jesse continues to struggle with his guilt.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012783.jpg"}, {"id": 12248, "season": 5, "number": 11, "name": "Confessions", "rating": 8.1, "airdate": "2013-08-25", "runtime": 60, "summary": "<p>Jesse decides to make a change, while Walt and Skyler try to deal with an unexpected demand.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012784.jpg"}, {"id": 12249, "season": 5, "number": 12, "name": "Rabid Dog", "rating": 7.3, "airdate": "2013-09-01", "runtime": 60, "summary": "<p>An unusual strategy starts to bear fruit, while plans are set in motion that could change everything.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012785.jpg"}, {"id": 12250, "season": 5, "number": 13, "name": "To'hajiilee", "rating": 8.3, "airdate": "2013-09-08", "runtime": 60, "summary": "<p>Things heat up for Walt in unexpected ways.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012786.jpg"}, {"id": 12251, "season": 5, "number": 14, "name": "Ozymandias", "rating": 9.1, "airdate": "2013-09-15", "runtime": 60, "summary": "<p>Everyone copes with radically changed circumstances.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012787.jpg"}, {"id": 12252, "season": 5, "number": 15, "name": "Granite State", "rating": 8.2, "airdate": "2013-09-22", "runtime": 60, "summary": "<p>Events set in motion long ago move toward a conclusion.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012788.jpg"}, {"id": 12253, "season": 5, "number": 16, "name": "Felina", "rating": 8, "airdate": "2013-09-29", "runtime": 60, "summary": "<p>The acclaimed crime drama comes to a close in the series finale.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1012789.jpg"}]}, {"id": 82, "name": "Game of Thrones", "premiered": "2011-04-17", "ended": "2019-05-19", "rating": 8.9, "genres": ["Drama", "Adventure", "Fantasy"], "summary": "<p>Based on the bestselling book series <i>A Song of Ice and Fire</i> by George R.R. Martin, this sprawling new HBO drama is set in a world where summers span decades and winters can last a lifetime. From the scheming south and the savage eastern lands, to the frozen north and ancient Wall that protects the realm from the mysterious darkness beyond, the powerful families of the Seven Kingdoms are locked in a battle for the Iron Throne. This is a story of duplicity and treachery, nobility and honor, conquest and triumph. In the <b>Game of Thrones</b>, you either win or you die.</p>", "poster": "https://static.tvmaze.com/uploads/images/original_untouched/498/1245274.jpg", "backdrop": "https://static.tvmaze.com/uploads/images/original_untouched/213/533549.jpg", "episodes": [{"id": 4952, "season": 1, "number": 1, "name": "Winter is Coming", "rating": 8.2, "airdate": "2011-04-17", "runtime": 60, "summary": "<p>Lord Eddard Stark, ruler of the North, is summoned to court by his old friend, King Robert Baratheon, to serve as the King's Hand. Eddard reluctantly agrees after learning of a possible threat to the King's life. Eddard's bastard son Jon Snow must make a painful decision about his own future, while in the distant east Viserys Targaryen plots to reclaim his father's throne, usurped by Robert, by selling his sister in marriage.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195111.jpg"}, {"id": 4953, "season": 1, "number": 2, "name": "The Kingsroad", "rating": 8.2, "airdate": "2011-04-24", "runtime": 60, "summary": "<p>An incident on the Kingsroad threatens Eddard and Robert's friendship. Jon and Tyrion travel to the Wall, where they discover that the reality of the Night's Watch may not match the heroic image of it.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195110.jpg"}, {"id": 4954, "season": 1, "number": 3, "name": "Lord Snow", "rating": 8, "airdate": "2011-05-01", "runtime": 60, "summary": "<p>Jon Snow attempts to find his place amongst the Night's Watch. Eddard and his daughters arrive at King's Landing.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195109.jpg"}, {"id": 4955, "season": 1, "number": 4, "name": "Cripples, Bastards, and Broken Things", "rating": 8.2, "airdate": "2011-05-08", "runtime": 60, "summary": "<p>Tyrion stops at Winterfell on his way home and gets a frosty reception from Robb Stark. Eddard's investigation into the death of his predecessor gets underway.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195107.jpg"}, {"id": 4956, "season": 1, "number": 5, "name": "The Wolf and the Lion", "rating": 8.5, "airdate": "2011-05-15", "runtime": 60, "summary": "<p>Catelyn's actions on the road have repercussions for Eddard. Tyrion enjoys the dubious hospitality of the Eyrie.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195106.jpg"}, {"id": 4957, "season": 1, "number": 6, "name": "A Golden Crown", "rating": 8.6, "airdate": "2011-05-22", "runtime": 60, "summary": "<p>Viserys is increasingly frustrated by the lack of progress towards gaining his crown.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195105.jpg"}, {"id": 4958, "season": 1, "number": 7, "name": "You Win or You Die", "rating": 8.8, "airdate": "2011-05-29", "runtime": 60, "summary": "<p>Eddard's investigations in King's Landing reach a climax and a dark secret is revealed.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195104.jpg"}, {"id": 4959, "season": 1, "number": 8, "name": "The Pointy End", "rating": 8.2, "airdate": "2011-06-05", "runtime": 60, "summary": "<p>Tyrion joins his father's army with unexpected allies. Events in King's Landing take a turn for the worse as Arya's lessons are put to the test.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195097.jpg"}, {"id": 4960, "season": 1, "number": 9, "name": "Baelor", "rating": 8.9, "airdate": "2011-06-12", "runtime": 60, "summary": "<p>Catelyn must negotiate with the irascible Lord Walder Frey.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195099.jpg"}, {"id": 4961, "season": 1, "number": 10, "name": "Fire and Blood", "rating": 8.9, "airdate": "2011-06-19", "runtime": 60, "summary": "<p>Daenerys must realize her destiny. Jaime finds himself in an unfamiliar predicament.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195102.jpg"}, {"id": 4962, "season": 2, "number": 1, "name": "The North Remembers", "rating": 8.2, "airdate": "2012-04-01", "runtime": 60, "summary": "<p>War grips the continent of Westeros. As Tyrion Lannister tries to take his strong-willed nephew in hand in King's Landing, Stannis Baratheon launches his own campaign to take the Iron Throne with the help of a mysterious priestess. In the east, Daenerys must lead her retinue through a desolate wasteland whilst beyond the Wall the Night's Watch seeks the aid of a wildling.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195118.jpg"}, {"id": 4963, "season": 2, "number": 2, "name": "The Night Lands", "rating": 7.8, "airdate": "2012-04-08", "runtime": 60, "summary": "<p>Stannis uses Ser Davos to seek out new allies for his war with the Lannisters. On the road north, Arya confides in Gendry. Robb Stark sends Theon Greyjoy to win an alliance with his father and the fierce warriors of the Iron Islands. Cersei and Tyrion clash on how to rule in King's Landing.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195119.jpg"}, {"id": 4964, "season": 2, "number": 3, "name": "What is Dead May Never Die", "rating": 8.2, "airdate": "2012-04-15", "runtime": 60, "summary": "<p>Catelyn Stark treats with King Renly in the hope of winning an alliance. Tyrion undertakes a complex plan in King's Landing to expose an enemy. At Winterfell, Bran's dreams continue to trouble him.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195120.jpg"}, {"id": 4965, "season": 2, "number": 4, "name": "Garden of Bones", "rating": 8.2, "airdate": "2012-04-22", "runtime": 60, "summary": "<p>Tyrion attempts to restrain Joffrey's cruelty. Catelyn attempts to broker a peace between Stannis and Renly. Daenerys and her followers arrive at the great city of Qarth and hope to find refuge there. Arya and Gendry arrive at Harrenhal, a great castle now under Lannister occupation.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195121.jpg"}, {"id": 4966, "season": 2, "number": 5, "name": "The Ghost of Harrenhal", "rating": 7.9, "airdate": "2012-04-29", "runtime": 60, "summary": "<p>Confusion rages in the Stormlands in the wake of a devastating reversal. Catelyn must flee with a new ally, whilst Littlefinger sees an opportunity in the chaos. Theon seeks to prove himself to his father in battle. Arya receives a promise from the enigmatic Jaqen H'ghar. The Night's Watch arrives at the Fist of the First Men. Daenerys Targaryen receives a marriage proposal.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195122.jpg"}, {"id": 4967, "season": 2, "number": 6, "name": "The Old Gods and the New", "rating": 8.8, "airdate": "2012-05-06", "runtime": 60, "summary": "<p>Arya has a surprise visitor; Dany vows to take what is hers; Joffrey meets his subjects; Qhorin gives Jon a chance to prove himself.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195123.jpg"}, {"id": 4968, "season": 2, "number": 7, "name": "A Man Without Honor", "rating": 8.2, "airdate": "2012-05-13", "runtime": 60, "summary": "<p>Jaime meets a relative; Theon hunts; Dany receives an invitation.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195125.jpg"}, {"id": 4969, "season": 2, "number": 8, "name": "The Prince of Winterfell", "rating": 8.3, "airdate": "2012-05-20", "runtime": 60, "summary": "<p>Theon holds the fort; Arya calls in her debt with Jaqen; Robb is betrayed; Stannis and Davos approach their destination.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195126.jpg"}, {"id": 4970, "season": 2, "number": 9, "name": "Blackwater", "rating": 9.2, "airdate": "2012-05-27", "runtime": 60, "summary": "<p>A massive battle rages for control of King's Landing and the Iron Throne.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195127.jpg"}, {"id": 4971, "season": 2, "number": 10, "name": "Valar Morghulis", "rating": 9, "airdate": "2012-06-03", "runtime": 60, "summary": "<p>Tyrion awakens to a changed situation. King Joffrey doles out rewards to his subjects. As Theon stirs his men to action, Luwin offers some final advice. Brienne silences Jaime; Arya receives a gift from Jaqen; Dany goes to a strange place; Jon proves himself to Qhorin.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195128.jpg"}, {"id": 4972, "season": 3, "number": 1, "name": "Valar Dohaeris", "rating": 7.9, "airdate": "2013-03-31", "runtime": 60, "summary": "<p>\u00a0</p><p>Jon is brought before Mance Rayder, the King Beyond the Wall, while the Night's Watch survivors retreat south. In King's Landing, Tyrion asks for his reward. Littlefinger offers Sansa a way out. Cersei hosts a dinner for the royal family. Daenerys sails into Slaver's Bay.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195037.jpg"}, {"id": 4973, "season": 3, "number": 2, "name": "Dark Wings, Dark Words", "rating": 7.9, "airdate": "2013-04-07", "runtime": 60, "summary": "<p>Sansa says too much. Shae asks Tyrion for a favor. Jaime finds a way to pass the time. Arya runs into the Brotherhood Without Banners.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195038.jpg"}, {"id": 4974, "season": 3, "number": 3, "name": "Walk of Punishment", "rating": 8.3, "airdate": "2013-04-14", "runtime": 60, "summary": "<p>Tyrion shoulders new responsibilities. Jon is taken to the Fist of the First Men. Daenerys meets with the slavers. Jaime strikes a deal with his captors.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195039.jpg"}, {"id": 4975, "season": 3, "number": 4, "name": "And Now His Watch is Ended", "rating": 8.9, "airdate": "2013-04-21", "runtime": 60, "summary": "<p>The Night's Watch takes stock. Varys meets his better. Arya is taken to the commander of the Brotherhood. Daenerys exchanges a chain for a Whip.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195040.jpg"}, {"id": 4976, "season": 3, "number": 5, "name": "Kissed by Fire", "rating": 8.7, "airdate": "2013-04-28", "runtime": 60, "summary": "<p>The Hound is judged by the gods; Jaime is judged by men. Jon proves himself; Robb is betrayed. Tyrion learns the cost of weddings.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195041.jpg"}, {"id": 4977, "season": 3, "number": 6, "name": "The Climb", "rating": 8.3, "airdate": "2013-05-05", "runtime": 60, "summary": "<p>Tywin plans strategic unions for the Lannisters. Melisandre visits the Riverlands. Robb weighs a compromise to repair his alliance with House Frey. Roose Bolton decides what to do with Jaime Lannister. Jon, Ygritte and the Wildlings face a daunting climb.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195042.jpg"}, {"id": 4978, "season": 3, "number": 7, "name": "The Bear and the Maiden Fair", "rating": 7.9, "airdate": "2013-05-12", "runtime": 60, "summary": "<p>Daenerys exchanges gifts with a slave lord outside Yunkai. As Sansa frets about her prospects, Shae chafes at Tyrion's new situation. Tywin counsels the king, and Melisandre reveals a secret to Gendry. Brienne faces a formidable foe in Harrenhal.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195043.jpg"}, {"id": 4979, "season": 3, "number": 8, "name": "Second Sons", "rating": 8.6, "airdate": "2013-05-19", "runtime": 60, "summary": "<p>King's Landing hosts a wedding, and Tyrion and Sansa spend the night together. Daenerys meets the Titan's Bastard. Davos demands proof from Melisandre. Sam and Gilly meet an older Gentleman.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195044.jpg"}, {"id": 4980, "season": 3, "number": 9, "name": "The Rains of Castamere", "rating": 9.1, "airdate": "2013-06-02", "runtime": 60, "summary": "<p>Robb presents himself to Walder Frey, and Edmure meets his bride. Jon faces his harshest test yet. Bran discovers a new gift. Daario and Jorah debate how to take Yunkai. House Frey joins with House Tully.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195045.jpg"}, {"id": 4981, "season": 3, "number": 10, "name": "Mhysa", "rating": 8, "airdate": "2013-06-09", "runtime": 60, "summary": "<p>Joffrey challenges Tywin. Bran tells a ghost story. In Dragonstone, mercy comes from strange quarters. Daenerys waits to see if she is a conqueror or a liberator.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195047.jpg"}, {"id": 4982, "season": 4, "number": 1, "name": "Two Swords", "rating": 8.2, "airdate": "2014-04-06", "runtime": 60, "summary": "<p>Tyrion welcomes a guest to King's Landing. At Castle Black, Jon Snow finds himself unwelcome. Dany is pointed to Meereen, the mother of all slave cities. Arya runs into an old friend.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195069.jpg"}, {"id": 4983, "season": 4, "number": 2, "name": "The Lion and the Rose", "rating": 9, "airdate": "2014-04-13", "runtime": 60, "summary": "<p>Tyrion lends Jaime a hand. Joffrey and Margaery host a breakfast. At Dragonstone, Stannis loses patience with Davos. Ramsay finds a purpose for his pet. North of the Wall, Bran sees where they must go.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195070.jpg"}, {"id": 4984, "season": 4, "number": 3, "name": "Breaker of Chains", "rating": 7.9, "airdate": "2014-04-20", "runtime": 60, "summary": "<p>Tyrion ponders his options. Tywin extends an olive branch. Sam realizes Castle Black isn't safe, and Jon proposes a bold plan. The Hound teaches Arya the way things are. Dany chooses her Champion.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195071.jpg"}, {"id": 4985, "season": 4, "number": 4, "name": "Oathkeeper", "rating": 7.9, "airdate": "2014-04-27", "runtime": 60, "summary": "<p>Dany balances justice and mercy. Jaime tasks Brienne with his honor. Jon secures volunteers while Bran, Jojen, Meera and Hodor stumble on shelter.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195072.jpg"}, {"id": 4986, "season": 4, "number": 5, "name": "First of His Name", "rating": 7.8, "airdate": "2014-05-04", "runtime": 60, "summary": "<p>Cersei and Tywin plot the Crown's next move. Dany discusses future plans. Jon embarks on a new mission.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195073.jpg"}, {"id": 4987, "season": 4, "number": 6, "name": "The Laws of Gods and Men", "rating": 8.4, "airdate": "2014-05-11", "runtime": 60, "summary": "<p>Stannis and Davos set sail with a new strategy. Dany meets with supplicants. Tyrion faces down his father in the throne room.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195075.jpg"}, {"id": 4988, "season": 4, "number": 7, "name": "Mockingbird", "rating": 8.2, "airdate": "2014-05-18", "runtime": 60, "summary": "<p>Tyrion enlists an unlikely ally. Daario entreats Dany to allow him to do what he does best. Jon's warnings about the Wall's vulnerability fall on deaf ears. Brienne follows a new lead on the road with Pod.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195076.jpg"}, {"id": 4989, "season": 4, "number": 8, "name": "The Mountain and the Viper", "rating": 8.8, "airdate": "2014-06-01", "runtime": 60, "summary": "<p>Mole's Town receives unexpected visitors. Littlefinger's motives are questioned. Ramsay attempts to prove himself to his father. Tyrion's fate is decided.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195077.jpg"}, {"id": 4990, "season": 4, "number": 9, "name": "The Watchers on the Wall", "rating": 8.7, "airdate": "2014-06-08", "runtime": 60, "summary": "<p>Jon Snow and the rest of the Night's Watch face the biggest challenge to the Wall yet.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195078.jpg"}, {"id": 4991, "season": 4, "number": 10, "name": "The Children", "rating": 8.3, "airdate": "2014-06-15", "runtime": 60, "summary": "<p>An unexpected arrival north of the Wall changes circumstances. Dany is forced to face harsh realities. Bran learns more of his destiny. Tyrion sees the truth of his situation.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195079.jpg"}, {"id": 116522, "season": 5, "number": 1, "name": "The Wars to Come", "rating": 7.6, "airdate": "2015-04-12", "runtime": 60, "summary": "<p>Varys discusses a conspiracy with Tyrion; Daenerys' rule faces a new threat; Jon finds himself between two kings; and Cersei and Jaime try to move on from Tywin's demise.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195080.jpg"}, {"id": 144328, "season": 5, "number": 2, "name": "The House of Black and White", "rating": 7.6, "airdate": "2015-04-19", "runtime": 60, "summary": "<p>Arya arrives in Braavos; Brienne and Podrick find danger while traveling; Cersei worries about Myrcella in Dorne when Ellaria Sand seeks revenge for Oberyn's death; Jon is tempted by Stannis.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195081.jpg"}, {"id": 144329, "season": 5, "number": 3, "name": "High Sparrow", "rating": 7.6, "airdate": "2015-04-26", "runtime": 60, "summary": "<p>Cersei meets the High Sparrow after learning of a clergyman's embarrassing tale. Meanwhile, Davos talks to Jon about the future of Winterfell, where Ramsay Snow has just learned the identity of his future bride; Arya grows impatient doing menial tasks in the House of Black and White; and Tyrion searches for more comfortable surroundings on a long trip with Varys.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195082.jpg"}, {"id": 144330, "season": 5, "number": 4, "name": "Sons of the Harpy", "rating": 7.4, "airdate": "2015-05-03", "runtime": 60, "summary": "<p>The Faith Militant grow increasingly aggressive. Jaime and Bronn head south. Ellaria and the Sand Snakes vow vengeance.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195083.jpg"}, {"id": 151777, "season": 5, "number": 5, "name": "Kill the Boy", "rating": 7.6, "airdate": "2015-05-10", "runtime": 60, "summary": "<p>Dany makes a difficult decision in Meereen. Jon recruits the help of an unexpected ally. Brienne searches for Sansa. Theon remains under Ramsay's control.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195084.jpg"}, {"id": 152766, "season": 5, "number": 6, "name": "Unbowed, Unbent, Unbroken", "rating": 7, "airdate": "2015-05-17", "runtime": 60, "summary": "<p>Arya trains. Jorah and Tyrion run into slavers. Trystane and Myrcella make plans. Jaime and Bronn reach their destination. The Sand Snakes attack.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195085.jpg"}, {"id": 153327, "season": 5, "number": 7, "name": "The Gift", "rating": 8, "airdate": "2015-05-24", "runtime": 60, "summary": "<p>Jon prepares for conflict. Sansa tries to talk to Theon. Brienne waits for a sign. Stannis remains stubborn. Jaime attempts to reconnect with family.</p><p><br /><br />\u00a0</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195086.jpg"}, {"id": 155299, "season": 5, "number": 8, "name": "Hardhome", "rating": 8.8, "airdate": "2015-05-31", "runtime": 60, "summary": "<p>Arya makes progress in her training. Sansa confronts an old friend. Cersei struggles. Jon travels.</p><p><br /><br />\u00a0</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195087.jpg"}, {"id": 160040, "season": 5, "number": 9, "name": "The Dance of Dragons", "rating": 7.9, "airdate": "2015-06-07", "runtime": 60, "summary": "<p>Stannis confronts a troubling decision. Jon returns to The Wall. Mace visits the Iron Bank. Arya encounters someone from her past. Dany reluctantly oversees a traditional celebration of athleticism.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/211/529615.jpg"}, {"id": 162186, "season": 5, "number": 10, "name": "Mother's Mercy", "rating": 7.9, "airdate": "2015-06-14", "runtime": 60, "summary": "<p>Cersei seeks forgiveness; Jon faces a new challenge; Arya plots to cross a name off her list; Tyrion sees a familiar face; and Daenerys finds herself surrounded by strangers.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/478/1195088.jpg"}, {"id": 560813, "season": 6, "number": 1, "name": "The Red Woman", "rating": 7.4, "airdate": "2016-04-24", "runtime": 60, "summary": "<p>Jon Snow is dead. Daenerys meets a strong man. Cersei sees her daughter again.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/56/142371.jpg"}, {"id": 664672, "season": 6, "number": 2, "name": "Home", "rating": 7.8, "airdate": "2016-05-01", "runtime": 60, "summary": "<p>Bran trains with the Three-Eyed Raven. In King's Landing, Jaime advises Tommen. Tyrion demands good news, but has to make his own. At Castle Black, the Night's Watch stands behind Thorne. Ramsay Bolton proposes a plan, and Balon Greyjoy entertains other proposals.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/56/142372.jpg"}, {"id": 664673, "season": 6, "number": 3, "name": "Oathbreaker", "rating": 7.4, "airdate": "2016-05-08", "runtime": 60, "summary": "<p>Daenerys meets her future. Bran meets the past. Tommen confronts the High Sparrow. Arya trains to be No One. Varys finds an answer. Ramsay gets a gift.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/56/142370.jpg"}, {"id": 664674, "season": 6, "number": 4, "name": "Book of the Stranger", "rating": 7.8, "airdate": "2016-05-15", "runtime": 60, "summary": "<p>Tyrion strikes a deal. Jorah and Daario undertake a difficult task. Jaime and Cersei try to improve their situation.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/56/142273.jpg"}, {"id": 664675, "season": 6, "number": 5, "name": "The Door", "rating": 7.9, "airdate": "2016-05-22", "runtime": 60, "summary": "<p>Tyrion seeks a strange ally. Bran learns a great deal. Brienne goes on a mission. Arya is given a chance to prove herself.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/60/150273.jpg"}, {"id": 664676, "season": 6, "number": 6, "name": "Blood of My Blood", "rating": 7.5, "airdate": "2016-05-29", "runtime": 60, "summary": "<p>An old foe comes back into the picture. Gilly meets Sam's family. Arya faces a difficult choice. Jaime faces off against the High Sparrow.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/60/150274.jpg"}, {"id": 717449, "season": 6, "number": 7, "name": "The Broken Man", "rating": 7.5, "airdate": "2016-06-05", "runtime": 60, "summary": "<p>The High Sparrow eyes another target. Jaime confronts a hero. Arya makes a plan. The North is reminded.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/60/150275.jpg"}, {"id": 729573, "season": 6, "number": 8, "name": "No One", "rating": 7.2, "airdate": "2016-06-12", "runtime": 60, "summary": "<p>Jaime encounters a hero; the High Sparrow fixates on another prey; Arya hatches a new plan; Yara and Theon plot their next move; Olenna and Cersei discuss their families' futures.</p><p>\u00a0</p><p>While Jaime weighs his options, Cersei answers a request. Tyrion's plans bear fruit. Arya faces a new test.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/61/153044.jpg"}, {"id": 729574, "season": 6, "number": 9, "name": "Battle of the Bastards", "rating": 8.4, "airdate": "2016-06-19", "runtime": 60, "summary": "<p>Ramsay surprises his audience. Jon retaliates. Dany is true to her word.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/62/155042.jpg"}, {"id": 729575, "season": 6, "number": 10, "name": "The Winds of Winter", "rating": 8.9, "airdate": "2016-06-26", "runtime": 69, "summary": "<p>Alliances are made, the High Sparrow is holding trials at King's Landing, Daenerys is sailing for the Seven Kingdoms and a new King of the North is crowned.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/63/157920.jpg"}, {"id": 937256, "season": 7, "number": 1, "name": "Dragonstone", "rating": 7.3, "airdate": "2017-07-16", "runtime": 60, "summary": "<p>Jon organizes the defense of the North. Cersei tries to even the odds. Daenerys comes home.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/120/302038.jpg"}, {"id": 1221410, "season": 7, "number": 2, "name": "Stormborn", "rating": 7.5, "airdate": "2017-07-23", "runtime": 60, "summary": "<p>Daenerys receives an unexpected visitor. Jon faces a revolt. Tyrion plans the conquest of Westeros.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/120/302047.jpg"}, {"id": 1221411, "season": 7, "number": 3, "name": "The Queen's Justice", "rating": 7.7, "airdate": "2017-07-30", "runtime": 60, "summary": "<p>Daenerys holds court. Cersei returns a gift. Jaime learns from his mistakes.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/122/306938.jpg"}, {"id": 1221412, "season": 7, "number": 4, "name": "The Spoils of War", "rating": 8.1, "airdate": "2017-08-06", "runtime": 60, "summary": "<p>Arya gets to the final destination. Daenerys takes it upon herself to strike back.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/123/307677.jpg"}, {"id": 1221413, "season": 7, "number": 5, "name": "Eastwatch", "rating": 7.7, "airdate": "2017-08-13", "runtime": 60, "summary": "<p>Daenerys demands loyalty from the surviving Lannister soldiers; Jon heeds Bran's warning about White Walkers on the move; Cersei vows to vanquish anyone or anything that stands in her way.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/124/310839.jpg"}, {"id": 1221414, "season": 7, "number": 6, "name": "Beyond the Wall", "rating": 8, "airdate": "2017-08-20", "runtime": 60, "summary": "<p>Jon's mission continues north of the wall, but the odds against his ragged band of misfits may be greater than he imagined.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/125/312651.jpg"}, {"id": 1221415, "season": 7, "number": 7, "name": "The Dragon and the Wolf", "rating": 8.1, "airdate": "2017-08-27", "runtime": 60, "summary": "<p>Cersei sits on the Iron Throne; Daenerys sails across the Narrow Sea; Jon Snow is King in the North, and winter is finally here.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/125/314502.jpg"}, {"id": 1590943, "season": 8, "number": 1, "name": "Winterfell", "rating": 7, "airdate": "2019-04-14", "runtime": 60, "summary": "<p>Arriving at Winterfell, Jon and Daenerys struggle to unite a divided North. Jon gets some big news.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/191/479477.jpg"}, {"id": 1623964, "season": 8, "number": 2, "name": "A Knight of the Seven Kingdoms", "rating": 7, "airdate": "2019-04-21", "runtime": 60, "summary": "<p>Jaime faces judgement and Winterfell prepares for the battle to come.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/192/482451.jpg"}, {"id": 1623965, "season": 8, "number": 3, "name": "The Long Night", "rating": 7.2, "airdate": "2019-04-28", "runtime": 90, "summary": "<p>Winterfell fights the Army of the Dead.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/192/482465.jpg"}, {"id": 1623966, "season": 8, "number": 4, "name": "The Last of the Starks", "rating": 6.1, "airdate": "2019-05-05", "runtime": 78, "summary": "<p>The survivors plan their next steps; Cersei makes a power move.</p><p>\u00a0</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/195/487839.jpg"}, {"id": 1623967, "season": 8, "number": 5, "name": "The Bells", "rating": 6.2, "airdate": "2019-05-12", "runtime": 79, "summary": "<p>Varys betrays his queen, and Daenerys brings her forces to King's Landing.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/196/491994.jpg"}, {"id": 1623968, "season": 8, "number": 6, "name": "The Iron Throne", "rating": 5.3, "airdate": "2019-05-19", "runtime": 80, "summary": "<p>In the aftermath of the devastating attack on King's Landing, Daenerys must face the survivors.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/198/495648.jpg"}]}, {"id": 618, "name": "Better Call Saul", "premiered": "2015-02-08", "ended": "2022-08-15", "rating": 8.6, "genres": ["Drama", "Crime", "Legal"], "summary": "<p><b>Better Call Saul</b> is the prequel to the award-winning series Breaking Bad, set six years before Saul Goodman became Walter White's lawyer. When we meet him, the man who will become Saul Goodman is known as Jimmy McGill, a small-time lawyer searching for his destiny, and, more immediately, hustling to make ends meet. Working alongside, and often against, Jimmy is \"fixer\" Mike Ehrmantraut, a beloved character introduced in Breaking Bad. The series will track Jimmy's transformation into Saul Goodman, the man who puts \"criminal\" in \"criminal lawyer.</p>", "poster": "https://static.tvmaze.com/uploads/images/original_untouched/501/1253515.jpg", "backdrop": "https://static.tvmaze.com/uploads/images/original_untouched/118/297100.jpg", "episodes": [{"id": 57360, "season": 1, "number": 1, "name": "Uno", "rating": 7.4, "airdate": "2015-02-08", "runtime": 60, "summary": "<p>Jimmy works his magic in the courtroom. Unexpected inspiration leads him to an unconventional pursuit of potential clients.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998482.jpg"}, {"id": 57361, "season": 1, "number": 2, "name": "Mijo", "rating": 7.8, "airdate": "2015-02-09", "runtime": 60, "summary": "<p>As his troubles escalate to a boiling point, Jimmy finds himself in dire straits. An act of carelessness puts Chuck at risk.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998483.jpg"}, {"id": 109590, "season": 1, "number": 3, "name": "Nacho", "rating": 7.7, "airdate": "2015-02-16", "runtime": 60, "summary": "<p>Jimmy pulls out all the stops to prove that a dangerous client is innocent, even though it causes some friction with Kim.<br></p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998484.jpg"}, {"id": 109591, "season": 1, "number": 4, "name": "Hero", "rating": 7.6, "airdate": "2015-02-23", "runtime": 60, "summary": "<p>Jimmy conjures up a bold plan to solicit new clients, but has to face the consequences when the scheme strains his relationship with a rival firm.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998485.jpg"}, {"id": 109592, "season": 1, "number": 5, "name": "Alpine Shepherd Boy", "rating": 7.2, "airdate": "2015-03-02", "runtime": 60, "summary": "<p>When his efforts to drum up new business are interrupted by alarming news, Jimmy is pressured to make a difficult choice.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998486.jpg"}, {"id": 109593, "season": 1, "number": 6, "name": "Five-O", "rating": 8.2, "airdate": "2015-03-09", "runtime": 60, "summary": "<p>Mike's tragic past comes back to haunt him, and he's forced to seek help from an unusual source. Meanwhile, Jimmy's moral compass is put to the test.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998487.jpg"}, {"id": 109594, "season": 1, "number": 7, "name": "Bingo", "rating": 7.8, "airdate": "2015-03-16", "runtime": 60, "summary": "<p>Jimmy meets with potential new clients. Then, when given the opportunity to do the right thing, he cashes in a favor from an unlikely ally.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998488.jpg"}, {"id": 109595, "season": 1, "number": 8, "name": "Rico", "rating": 7.7, "airdate": "2015-03-23", "runtime": 60, "summary": "<p>Jimmy shows Chuck that he's willing to do almost anything to win a case, even if it means getting his hands dirty.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998489.jpg"}, {"id": 109596, "season": 1, "number": 9, "name": "Pimento", "rating": 8.7, "airdate": "2015-03-30", "runtime": 60, "summary": "<p>Chuck urges Jimmy to accept a harsh truth. Meanwhile, a deal threatens to go off the rails when Mike's ability to complete a job is called into question.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998490.jpg"}, {"id": 109597, "season": 1, "number": 10, "name": "Marco", "rating": 7.4, "airdate": "2015-04-06", "runtime": 60, "summary": "<p>In the aftermath of recent events, Jimmy seizes the opportunity to reconnect with an old friend. Meanwhile, Chuck adjusts to a new way of life.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998491.jpg"}, {"id": 470535, "season": 2, "number": 1, "name": "Switch", "rating": 7.6, "airdate": "2016-02-15", "runtime": 60, "summary": "<p>Jimmy and Kim's relationship takes a new turn. Mike decides it's for the best to sever his affiliation with an unrestrained associate.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998493.jpg"}, {"id": 603277, "season": 2, "number": 2, "name": "Cobbler", "rating": 7.8, "airdate": "2016-02-22", "runtime": 60, "summary": "<p>Mike brokers a deal in order to keep a potentially messy situation intact; Jimmy tries to exonerate an eccentric client.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998494.jpg"}, {"id": 603278, "season": 2, "number": 3, "name": "Amarillo", "rating": 7.9, "airdate": "2016-02-29", "runtime": 60, "summary": "<p>Jimmy's client outreach efforts succeed, and he exhibits new heights of showmanship; Mike is puzzled by Stacey's upsetting news.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998495.jpg"}, {"id": 628774, "season": 2, "number": 4, "name": "Gloves Off", "rating": 8.2, "airdate": "2016-03-07", "runtime": 60, "summary": "<p>Jimmy's actions unexpectedly create waves for Kim. Meanwhile, Mike cautiously weighs a lucrative proposal that might bring about dire consequences.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998496.jpg"}, {"id": 633518, "season": 2, "number": 5, "name": "Rebecca", "rating": 7.5, "airdate": "2016-03-14", "runtime": 60, "summary": "<p>Jimmy becomes frustrated with his restrictive work environment. Meanwhile, Kim pulls out all the stops to dig herself out of a seemingly bottomless hole at HHM.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998497.jpg"}, {"id": 636926, "season": 2, "number": 6, "name": "Bali Ha'i", "rating": 7.8, "airdate": "2016-03-21", "runtime": 60, "summary": "<p>Jimmy finds comfort in familiarity; Kim receives a life-changing proposal; when he is threatened, Mike finds himself pushed to the limit.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998498.jpg"}, {"id": 645687, "season": 2, "number": 7, "name": "Inflatable", "rating": 8, "airdate": "2016-03-28", "runtime": 60, "summary": "<p>Mike's growing frustration shows when his hand is forced, but with Jimmy's help, he works to keep the peace. Meanwhile, Jimmy boldly forges a new path forward.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998499.jpg"}, {"id": 645688, "season": 2, "number": 8, "name": "Fifi", "rating": 7.8, "airdate": "2016-04-04", "runtime": 60, "summary": "<p>Mike is determined to settle the score with a dangerous adversary. An unexpected opportunity to gain a competitive edge falls in Jimmy's lap.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998500.jpg"}, {"id": 645689, "season": 2, "number": 9, "name": "Nailed", "rating": 8.5, "airdate": "2016-04-11", "runtime": 60, "summary": "<p>Mike takes a methodical approach to his mission. Someone questions Chuck's capabilities. Jimmy faces a personal dilemma.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998501.jpg"}, {"id": 645691, "season": 2, "number": 10, "name": "Klick", "rating": 7.9, "airdate": "2016-04-18", "runtime": 60, "summary": "<p>Jimmy is forced to make a hard choice. Mike takes matters into his own hands. Hamlin relays shocking news while Chuck's condition continues to evolve.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998502.jpg"}, {"id": 1041746, "season": 3, "number": 1, "name": "Mabel", "rating": 7.8, "airdate": "2017-04-10", "runtime": 70, "summary": "<p>Jimmy and Chuck's relationship deteriorates; Kim feels the pressure of running her own firm; Mike investigates the note left on his car.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998503.jpg"}, {"id": 1051911, "season": 3, "number": 2, "name": "Witness", "rating": 8, "airdate": "2017-04-17", "runtime": 70, "summary": "<p>Jimmy and Kim hire an assistant; Mike seeks out a mysterious acquaintance; Chuck uses the law to gain an advantage over Jimmy.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998504.jpg"}, {"id": 1051912, "season": 3, "number": 3, "name": "Sunk Costs", "rating": 7.8, "airdate": "2017-04-24", "runtime": 70, "summary": "<p>Jimmy decides to represent a new client to Kim's dismay; Mike meets a formidable ally who gives a tempting offer.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998505.jpg"}, {"id": 1051913, "season": 3, "number": 4, "name": "Sabrosito", "rating": 8, "airdate": "2017-05-01", "runtime": 70, "summary": "<p>Jimmy asks a favor of Mike; new complications disrupt Salamancas' business; Chuck and Jimmy struggle with a compromise.</p><p></p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998506.jpg"}, {"id": 1051914, "season": 3, "number": 5, "name": "Chicanery", "rating": 8.8, "airdate": "2017-05-08", "runtime": 70, "summary": "<p>Kim and Jimmy face off with an adversary; Jimmy looks to Chuck's past to secure his future; Jimmy loses an ally and gains another.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998507.jpg"}, {"id": 1051915, "season": 3, "number": 6, "name": "Off Brand", "rating": 7.8, "airdate": "2017-05-15", "runtime": 70, "summary": "<p>Jimmy has a new endeavor; Chuck pushes himself to the limit; Nacho finds himself in a power struggle.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998508.jpg"}, {"id": 1051916, "season": 3, "number": 7, "name": "Expenses", "rating": 7.8, "airdate": "2017-05-22", "runtime": 70, "summary": "<p>Jimmy tries to settle debts; Nacho reunites with an acquaintance; Mike helps Stacey with a project and makes a connection.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998509.jpg"}, {"id": 1156192, "season": 3, "number": 8, "name": "Slip", "rating": 7.8, "airdate": "2017-06-05", "runtime": 70, "summary": "<p>Jimmy is pushed to desperate measures; Nacho picks up a skill; Mike explores an alliance; Kim stands up to Hamlin.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998510.jpg"}, {"id": 1156193, "season": 3, "number": 9, "name": "Fall", "rating": 8.1, "airdate": "2017-06-12", "runtime": 77, "summary": "<p>Jimmy visits a friend and takes up an old pastime; Chuck and Hamlin argue over the future of the firm; Kim faces challenges.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998512.jpg"}, {"id": 1156194, "season": 3, "number": 10, "name": "Lantern", "rating": 8.8, "airdate": "2017-06-19", "runtime": 76, "summary": "<p>Kim takes time off; Jimmy tries to make amends; Nacho gambles with his future; Hamlin pushes Chuck to make a decision.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998513.jpg"}, {"id": 1474613, "season": 4, "number": 1, "name": "Smoke", "rating": 7.5, "airdate": "2018-08-06", "runtime": 60, "summary": "<p>Jimmy struggles to cope with Chuck's tragic death; Mike ponders his role at Madrigal; Howard makes a startling confession.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/163/409086.jpg"}, {"id": 1494753, "season": 4, "number": 2, "name": "Breathe", "rating": 7.8, "airdate": "2018-08-13", "runtime": 60, "summary": "<p>Jimmy seeks new employment; Gus navigates the fallout from Hector's collapse; Kim endeavors to support Jimmy in the wake of Chuck's death.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/164/410839.jpg"}, {"id": 1494754, "season": 4, "number": 3, "name": "Something Beautiful", "rating": 7.8, "airdate": "2018-08-20", "runtime": 60, "summary": "<p>Jimmy puts a risky plan into motion; as alliances shift, Nacho finds himself in the crosshairs; Kim contemplates her future.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/164/412337.jpg"}, {"id": 1494755, "season": 4, "number": 4, "name": "Talk", "rating": 7.5, "airdate": "2018-08-27", "runtime": 60, "summary": "<p>A restless Jimmy embarks on a new endeavor while Mike burns bridges; Kim pursues her bliss; Nacho tries to survive a turf war.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/165/414042.jpg"}, {"id": 1494756, "season": 4, "number": 5, "name": "Quite a Ride", "rating": 7.8, "airdate": "2018-09-03", "runtime": 60, "summary": "<p>Jimmy identifies a new market for his talents; Mike vets a potential partnership; Kim drives a hard bargain.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998517.jpg"}, {"id": 1512972, "season": 4, "number": 6, "name": "Pi\u00f1ata", "rating": 7.8, "airdate": "2018-09-10", "runtime": 60, "summary": "<p>While Jimmy dreams of Wexler-McGill, Kim makes a bold move; Mike puts a plan into motion for Gus.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/167/417665.jpg"}, {"id": 1515542, "season": 4, "number": 7, "name": "Something Stupid", "rating": 7.8, "airdate": "2018-09-17", "runtime": 60, "summary": "<p>Jimmy expands his business, but runs into a problem that only Kim can solve; Gus intervenes in Hector's medical care; Mike deals with a setback.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/168/420231.jpg"}, {"id": 1514806, "season": 4, "number": 8, "name": "Coushatta", "rating": 7.9, "airdate": "2018-09-24", "runtime": 60, "summary": "<p>Jimmy goes to great lengths to right a wrong, as Kim pulls out all the stops for a case; Mike lets his team blow off steam; Nacho receives a visitor.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/168/422222.jpg"}, {"id": 1514807, "season": 4, "number": 9, "name": "Wiedersehen", "rating": 8.3, "airdate": "2018-10-01", "runtime": 60, "summary": "<p>Jimmy and Kim unburden themselves, risking their relationship in the process; Nacho is forced to make the rounds with Lalo; Mike has cause to worry.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/399/998518.jpg"}, {"id": 1514808, "season": 4, "number": 10, "name": "Winner", "rating": 8.7, "airdate": "2018-10-08", "runtime": 60, "summary": "<p>Jimmy turns the page on his reputation; Lalo tracks a loose end in Gus' operation; Mike is forced to make a difficult decision.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/170/426447.jpg"}, {"id": 1759932, "season": 5, "number": 1, "name": "Magic Man", "rating": 7.8, "airdate": "2020-02-23", "runtime": 75, "summary": "<p>Now doing business as Saul Goodman, Jimmy unveils an unorthodox strategy for client development that tests Kim's tolerance of his new legal persona. Lalo searches for the mysterious Michael, only to discover a problem within his own operation.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/242/606787.jpg"}, {"id": 1759933, "season": 5, "number": 2, "name": "50% Off", "rating": 8, "airdate": "2020-02-24", "runtime": 60, "summary": "<p>Jimmy's promotional stunt has unintended consequences. Nacho takes extreme measures to earn Lalo's trust. Saul is a success at the courthouse, but still has yet to win Kim over.\u00a0Simmering with rage and self-loathing, Mike loses his temper.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/243/608325.jpg"}, {"id": 1793336, "season": 5, "number": 3, "name": "The Guy for This", "rating": 8.3, "airdate": "2020-03-02", "runtime": 75, "summary": "<p>Kim's confidence is tested when she's faced with a legal problem only she can solve.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/243/608336.jpg"}, {"id": 1793335, "season": 5, "number": 4, "name": "Namaste", "rating": 8, "airdate": "2020-03-09", "runtime": 60, "summary": "<p>As Jimmy doubles down on Saul Goodman, a deeply conflicted Kim brings him an interesting proposition. Gus makes a sacrifice in order to play the long game. Mike attempts to smooth things over with his family.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/245/613318.jpg"}, {"id": 1794666, "season": 5, "number": 5, "name": "Dedicado a Max", "rating": 8.3, "airdate": "2020-03-16", "runtime": 70, "summary": "<p>Mike makes an unexpected trip out of town; Kim makes a surprising decision as she grows closer to Jimmy over their determination to help a client.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/246/615824.jpg"}, {"id": 1794667, "season": 5, "number": 6, "name": "Wexler v. Goodman", "rating": 8.8, "airdate": "2020-03-23", "runtime": 70, "summary": "<p>Kim fears she is too late to stop Saul as she tries to reign in Jimmy's newest scheme; Mike increases the pressure on Lalo; Nacho struggles to gain support.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/247/619726.jpg"}, {"id": 1794668, "season": 5, "number": 7, "name": "JMM", "rating": 8.3, "airdate": "2020-03-30", "runtime": 68, "summary": "<p>Kim and Jimmy turn to Huell for help with a legal firewall; Jimmy is compromised as Kim struggles to work things out with her clients; despite the issues he faces, Gus navigates his way to build an empire; Mike tries to do damage control.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/248/621615.jpg"}, {"id": 1794669, "season": 5, "number": 8, "name": "Bagman", "rating": 8.9, "airdate": "2020-04-06", "runtime": 75, "summary": "<p>Jimmy is pushed to his limit as he strives to help a client only for the simple task to go awry; Mike tries to deal with angry cartel members; a surprise visitor meets Lalo.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/250/625584.jpg"}, {"id": 1794670, "season": 5, "number": 9, "name": "Bad Choice Road", "rating": 9.2, "airdate": "2020-04-13", "runtime": 85, "summary": "<p>In the wake of Jimmy's traumatic misadventure, Kim takes stock of what is important. Jimmy attempts to return to business as usual, but it's more difficult than anticipated. Gus and Mike set a plan in motion.<br />\u00a0</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/250/627471.jpg"}, {"id": 1794671, "season": 5, "number": 10, "name": "Something Unforgivable", "rating": 8.1, "airdate": "2020-04-20", "runtime": 85, "summary": "<p>Jimmy and Kim make a sideways move that takes a serious turn; Nacho gets closer to the cartel.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/252/631632.jpg"}, {"id": 2273239, "season": 6, "number": 1, "name": "Wine and Roses", "rating": 7.8, "airdate": "2022-04-18", "runtime": 60, "summary": "<p>Nacho runs for his life. Jimmy and Kim hatch a plan. Mike questions his allegiances.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1013168.jpg"}, {"id": 2273422, "season": 6, "number": 2, "name": "Carrot and Stick", "rating": 7.9, "airdate": "2022-04-18", "runtime": 60, "summary": "<p>Harsh realities dawn on Nacho. Gus investigates his suspicions.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/405/1013169.jpg"}, {"id": 2273423, "season": 6, "number": 3, "name": "Rock and Hard Place", "rating": 8.4, "airdate": "2022-04-25", "runtime": 60, "summary": "<p>Still on the run, Nacho is forced to choose where his loyalties lie. Jimmy doubles down.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/407/1017878.jpg"}, {"id": 2273424, "season": 6, "number": 4, "name": "Hit and Run", "rating": 8.1, "airdate": "2022-05-02", "runtime": 60, "summary": "<p>Gus takes extreme measures. Jimmy and Kim enlist a local pro to put on a show.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/407/1018713.jpg"}, {"id": 2273425, "season": 6, "number": 5, "name": "Black and Blue", "rating": 7.6, "airdate": "2022-05-09", "runtime": 60, "summary": "<p>While business booms for Jimmy, the vise tightens on the cat-and-mouse game between Gus and Lalo.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/408/1020644.jpg"}, {"id": 2273426, "season": 6, "number": 6, "name": "Axe and Grind", "rating": 7.5, "airdate": "2022-05-16", "runtime": 60, "summary": "<p>Kim and Jimmy enlist a knowledgeable contact. Howard scrutinizes Jimmy's business practices. Mike refuses to compromise as tensions mount within Gus' operation. Lalo interrogates a witness.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/409/1022730.jpg"}, {"id": 2273427, "season": 6, "number": 7, "name": "Plan and Execution", "rating": 8.8, "airdate": "2022-05-23", "runtime": 60, "summary": "<p>Jimmy and Kim deal with a last-minute snag in their plan.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/409/1024979.jpg"}, {"id": 2273428, "season": 6, "number": 8, "name": "Point and Shoot", "rating": 8.4, "airdate": "2022-07-11", "runtime": 60, "summary": "<p>An unexpected visitor forces Jimmy and Kim to face the consequences of their actions.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/415/1038965.jpg"}, {"id": 2355727, "season": 6, "number": 9, "name": "Fun and Games", "rating": 8.2, "airdate": "2022-07-18", "runtime": 60, "summary": "<p>Gus attempts to smooth things over with the cartel while Mike ties up loose ends north of the border.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/416/1040661.jpg"}, {"id": 2355728, "season": 6, "number": 10, "name": "Nippy", "rating": 7.7, "airdate": "2022-07-25", "runtime": 60, "summary": "<p>A new player gets in the game.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/417/1042767.jpg"}, {"id": 2355729, "season": 6, "number": 11, "name": "Breaking Bad", "rating": 8.3, "airdate": "2022-08-01", "runtime": 60, "summary": "<p>Emboldened by recent successes, partners throw caution to the wind and escalate their enterprise to new levels.\u00a0</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/417/1044637.jpg"}, {"id": 2355730, "season": 6, "number": 12, "name": "Waterworks", "rating": 8.2, "airdate": "2022-08-08", "runtime": 60, "summary": "<p>The stakes are raised when a discovery is made that will send shockwaves far and wide.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/418/1045841.jpg"}, {"id": 2355731, "season": 6, "number": 13, "name": "Saul Gone", "rating": 8.4, "airdate": "2022-08-15", "runtime": 72, "summary": "<p>The series finale.</p>", "image": "https://static.tvmaze.com/uploads/images/medium_landscape/418/1047113.jpg"}]}];
